public long maxSubarrayMod(long[] a, long m) {
    java.util.TreeSet<Long> seen = new java.util.TreeSet<>();
    long pre = 0, best = 0;
    for (long x : a) {
        pre = (pre + x % m) % m;            // reduce every step — no overflow
        best = Math.max(best, pre);          // subarray starting at index 0
        Long higher = seen.higher(pre);      // smallest stored prefix > pre
        if (higher != null) {
            best = Math.max(best, (pre - higher + m) % m);
        }
        seen.add(pre);
    }
    return best;
}
